public class SafePublication {
    private int data;
    private volatile boolean ready = false;

    public void writer() {
        data = 42; // Happens-before ready = true
        ready = true; 
    }

    public void reader() {
        if (ready) { // Happens-after writer's ready = true
            // Guaranteed to see data == 42
            System.out.println(data);
        }
    }
}
